import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷一·33","description":"易小帖 - 卷一·33","frontmatter":{"title":"卷一·33","description":"易小帖 - 卷一·33"},"headers":[],"relativePath":"zh/classics/yixiaotie/033.md","filePath":"zh/classics/yixiaotie/033.md"}'),o={name:"zh/classics/yixiaotie/033.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷一·33",tabindex:"-1"},[r("卷一·33 "),e("a",{class:"header-anchor",href:"#卷一·33","aria-label":"Permalink to “卷一·33”"},"​")],-1),e("p",null,"坎六四「樽酒簋貳」，此孔子所讀者。《象》曰「樽酒簋貳」是也。貳者副也，鄭康成曰：「天子大臣以王命出，會諸侯，主國尊棜簋副，設玄酒而用缶。」此自可據。而朱子以貳為益酒之貳，引酒正大祭三貳為註。則於簋貳為不通矣。於是引晁以道偽古本以為先儒皆簋字作句，以貳字連下讀，及註《象傳》辭則明與孔子所讀不合，乃又引晁氏據陸徳明《釋文》本謂，原無貳字，所當刪去，則不信孔子而信輓近作偽之小儒，大無理矣。據晁氏雲：先儒多此讀。考漢魏六朝，並無其人，惟虞仲翔易有「禮有副樽，故貳用缶」。則雖以貳字連下作說，而仍以貳字解樽棜之副，則仍以貳字句。觀其於《象傳》仍不去貳字可驗。且爻詞多有韻者，坎自六三至上六，皆有韻文字。樽酒與用缶、自牖三韻相協，簋貳其讀也。若曰樽酒簋，不惟孔子不然，文王演辭亦豈其然。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
